use std::process::ExitCode;
use std::sync::mpsc;

use wgpu::util::DeviceExt;

/// Values are generated and counted in kernels; this is the only host-side work
/// besides reading the job file and printing the result.
const WORKGROUP_SIZE: u32 = 256;
const MAX_BINS: u32 = 256;

const SHADER: &str = r#"
struct Params {
    count: u32,
    seed: u32,
    bins: u32,
    pad: u32,
}

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read_write> values: array<u32>;
@group(0) @binding(2) var<storage, read_write> counts: array<atomic<u32>>;

fn value_at(i: u32) -> u32 {
    let a = ((i % 40000u) * 1597u + params.seed + 51749u) % 40000u;
    let b = (a * a + a * 37u + 11u) % 40009u;
    let c = (b * 613u + 7919u) % 40009u;
    let d = (c + (i / 40000u) * 7919u) % 40009u;
    return d % 1000u;
}

@compute @workgroup_size(256)
fn generate(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.count) {
        return;
    }
    values[i] = value_at(i);
}

@compute @workgroup_size(256)
fn count(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.count) {
        return;
    }
    let bin = values[i] * params.bins / 1000u;
    atomicAdd(&counts[bin], 1u);
}
"#;

struct Job {
    count: u32,
    seed: u32,
    bins: u32,
}

fn read_job(path: &str) -> Result<Job, String> {
    let text = std::fs::read_to_string(path).map_err(|e| format!("cannot read {path}: {e}"))?;
    let fields: Vec<&str> = text.split_whitespace().collect();
    let [count, seed, bins] = fields[..] else {
        return Err(format!("expected '<count> <seed> <bins>' in {path}"));
    };
    let parse = |s: &str, name: &str| -> Result<u32, String> {
        s.parse::<u32>().map_err(|_| format!("{name} is not a whole number: {s}"))
    };
    let job = Job {
        count: parse(count, "count")?,
        seed: parse(seed, "seed")?,
        bins: parse(bins, "bins")?,
    };
    if job.count > 4_000_000 {
        return Err(format!("count out of range: {}", job.count));
    }
    if job.seed > 9999 {
        return Err(format!("seed out of range: {}", job.seed));
    }
    if !(1..=MAX_BINS).contains(&job.bins) {
        return Err(format!("bins out of range: {}", job.bins));
    }
    Ok(job)
}

fn run_on_gpu(job: &Job) -> Result<Vec<u32>, String> {
    let instance = wgpu::Instance::new(wgpu::InstanceDescriptor::new_without_display_handle());
    let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions {
        power_preference: wgpu::PowerPreference::HighPerformance,
        ..Default::default()
    }))
    .map_err(|e| format!("no GPU adapter: {e}"))?;
    let (device, queue) = pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor {
        label: Some("histogram"),
        ..Default::default()
    }))
    .map_err(|e| format!("no GPU device: {e}"))?;

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("histogram"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });

    let storage = |binding: u32| wgpu::BindGroupLayoutEntry {
        binding,
        visibility: wgpu::ShaderStages::COMPUTE,
        ty: wgpu::BindingType::Buffer {
            ty: wgpu::BufferBindingType::Storage { read_only: false },
            has_dynamic_offset: false,
            min_binding_size: None,
        },
        count: None,
    };
    let layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
        label: Some("histogram"),
        entries: &[
            wgpu::BindGroupLayoutEntry {
                binding: 0,
                visibility: wgpu::ShaderStages::COMPUTE,
                ty: wgpu::BindingType::Buffer {
                    ty: wgpu::BufferBindingType::Uniform,
                    has_dynamic_offset: false,
                    min_binding_size: None,
                },
                count: None,
            },
            storage(1),
            storage(2),
        ],
    });
    let pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
        label: Some("histogram"),
        bind_group_layouts: &[Some(&layout)],
        immediate_size: 0,
    });
    let make_pipeline = |entry: &str| {
        device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: Some(entry),
            layout: Some(&pipeline_layout),
            module: &module,
            entry_point: Some(entry),
            compilation_options: Default::default(),
            cache: None,
        })
    };
    let generate = make_pipeline("generate");
    let count = make_pipeline("count");

    // Zero-length buffers are not allowed, so an empty job still gets one slot.
    let value_slots = u64::from(job.count.max(1));
    let params = [job.count, job.seed, job.bins, 0u32];
    let params_bytes: Vec<u8> = params.iter().flat_map(|p| p.to_ne_bytes()).collect();
    let params_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("params"),
        contents: &params_bytes,
        usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
    });
    let values_buf = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("values"),
        size: value_slots * 4,
        usage: wgpu::BufferUsages::STORAGE,
        mapped_at_creation: false,
    });
    let counts_bytes = u64::from(MAX_BINS) * 4;
    let counts_buf = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("counts"),
        size: counts_bytes,
        usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC,
        mapped_at_creation: false,
    });
    let staging = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("staging"),
        size: counts_bytes,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });
    let bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some("histogram"),
        layout: &layout,
        entries: &[
            wgpu::BindGroupEntry {
                binding: 0,
                resource: params_buf.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 1,
                resource: values_buf.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 2,
                resource: counts_buf.as_entire_binding(),
            },
